```c
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int *a = (int *)malloc((size_t)n * sizeof(int));
    if (a == NULL) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    int visible = 0;
    int max_right = -1;

    for (int i = n - 1; i >= 0; i--) {
        if (a[i] > max_right) {
            visible++;
            max_right = a[i];
        }
    }

    printf("%d\n", n - visible);

    free(a);
    return 0;
}
```

